#!/usr/bin/env node
// Fills in an employee roster on top of the 8 real Central Group banners
// that scripts/setup.mjs always creates (see docs/sqlite/schema.sql). No
// network access, no production credentials — everything here is invented
// locally and encrypted with whatever COMPENSATION_ENCRYPTION_KEY already
// exists in .env.local (generated by `npm run setup`). Not meant to be mixed
// with real migrated data (see scripts/migrate_from_cloud.mjs for that
// instead).
//
// Usage:
//   npm run setup
//   npm run seed:demo
//
// Refuses to run if `employees` already has rows, unless --force is passed.

import { DatabaseSync } from "node:sqlite";
import { createCipheriv, randomBytes } from "crypto";
import { existsSync, readFileSync, mkdirSync, copyFileSync } from "fs";
import path from "path";

const root = path.resolve(import.meta.dirname, "..");
const dbPath = process.env.ROYALFLUSH_DB_PATH || path.join(root, "data", "royalflush.db");
const envLocalPath = path.join(root, ".env.local");
const uploadsRoot = process.env.ROYALFLUSH_UPLOADS_PATH || path.join(root, "data", "uploads");
const photoSourceDir = path.join(root, "assets", "employee-photos");
const force = process.argv.includes("--force");

// ── Deterministic per-employee RNG (same seed every reseed, so the fabricated
//    content — grades, achievements, career steps — is stable across resets
//    rather than reshuffling every time someone runs `npm run wipe-and-reseed`). ──
function mulberry32(seed) {
    let a = seed >>> 0;
    return function () {
        a |= 0; a = (a + 0x6D2B79F5) | 0;
        let t = Math.imul(a ^ (a >>> 15), 1 | a);
        t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
        return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
    };
}
function seedFromString(s) {
    let h = 2166136261;
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
    return h >>> 0;
}
function rngFor(name) { return mulberry32(seedFromString(name)); }
function pick(rng, arr) { return arr[Math.floor(rng() * arr.length)]; }
function pickN(rng, arr, n) {
    const pool = [...arr];
    const out = [];
    for (let i = 0; i < n && pool.length; i++) out.push(pool.splice(Math.floor(rng() * pool.length), 1)[0]);
    return out;
}
function rngInt(rng, min, max) { return Math.round(min + rng() * (max - min)); }

if (!existsSync(dbPath)) {
    console.error(`No database at ${dbPath} — run \`npm run setup\` first.`);
    process.exit(1);
}

const db = new DatabaseSync(dbPath);
const existingCount = db.prepare("SELECT COUNT(*) AS c FROM employees").get().c;
if (existingCount > 0 && !force) {
    console.error(`employees already has ${existingCount} row(s) — refusing to seed twice.`);
    console.error("Run `npm run wipe:sample-employees` for a clean slate, or pass --force if you understand the collision risk.");
    db.close();
    process.exit(1);
}

// ── Encryption (mirrors src/lib/crypto.ts's encryptAmount/encryptJson —
//    duplicated here since that file is TypeScript and this script is
//    plain .mjs) ────────────────────────────────────────────────────────

function loadEnvLocalKey() {
    const raw = existsSync(envLocalPath) ? readFileSync(envLocalPath, "utf8") : "";
    const match = raw.match(/^COMPENSATION_ENCRYPTION_KEY=(.+)$/m);
    if (!match) {
        console.error("No COMPENSATION_ENCRYPTION_KEY found in .env.local — run `npm run setup` first.");
        process.exit(1);
    }
    return Buffer.from(match[1].trim(), "base64");
}

const encryptionKey = loadEnvLocalKey();

function encryptString(plaintext) {
    const iv = randomBytes(12);
    const cipher = createCipheriv("aes-256-gcm", encryptionKey, iv);
    const ciphertext = Buffer.concat([cipher.update(plaintext, "utf8"), cipher.final()]);
    const tag = cipher.getAuthTag();
    return Buffer.concat([iv, tag, ciphertext]).toString("base64");
}

const encryptAmount = (value) => (value == null ? null : encryptString(String(value)));

// ── Employee roster, attached to the real banners already in the database
//    (Selfridges, Arnotts, Brown Thomas, de Bijenkorf, Illum, KaDeWe,
//    Rinascente, Globus — see docs/sqlite/schema.sql) ────────────────────

const FUNCTIONS = ["Leadership", "Product", "Human Resources", "Finance", "Marketing", "Operations"];

// Kept intentionally small (5 people) — enough to show a real reporting
// hierarchy, 2 companies, succession, and full ICPD data, without being
// mistaken for actual headcount. A future update can replace this roster
// entirely (via `npm run wipe:sample-employees && npm run seed:demo` after
// pulling the new code) without touching anything else in the database.
// name, banner, function, title, grade, dob, hireDate, effDate, readiness, status, reportsTo (name or null), resignDate, resignReason
const EMPLOYEES = [
    ["Robert King", "Selfridges", "Leadership", "Chief Executive Officer", "Exec", "1972-04-10", "2009-01-05", "2015-01-01", "High", "Active", null],
    ["Victor Pak", "Selfridges", "Product", "VP Product", "Exec", "1978-09-22", "2012-03-01", "2018-06-01", "High", "Active", "Robert King"],
    ["Helena Voss", "Selfridges", "Human Resources", "CHRO", "Exec", "1975-11-30", "2011-05-15", "2017-01-01", "High", "Active", "Robert King"],
    ["Alex Morgan", "Arnotts", "Product", "Senior Product Manager", "Manager", "1987-03-15", "2016-06-01", "2022-01-01", "High", "Active", "Victor Pak"],
    ["Sofia Martinez", "Arnotts", "Human Resources", "HR Director", "Manager", "1984-07-22", "2014-03-15", "2021-04-01", "High", "Active", "Helena Voss"],
];

const GRADE_COMP = {
    Exec: { base: [180000, 260000], sti: 0.3, lti: 0.25, bonus: [5000, 15000] },
    Manager: { base: [75000, 120000], sti: 0.18, lti: 0.1, bonus: [2000, 6000] },
    IC: { base: [40000, 70000], sti: 0.1, lti: 0, bonus: [0, 2000] },
};

function randInt(min, max) {
    return Math.round(min + Math.random() * (max - min));
}

function mockCompensation(grade) {
    const cfg = GRADE_COMP[grade];
    const base = randInt(cfg.base[0], cfg.base[1]);
    const stiTarget = Math.round(base * cfg.sti);
    const ltiTarget = cfg.lti > 0 ? Math.round(base * cfg.lti) : null;
    const otherBonus = randInt(cfg.bonus[0], cfg.bonus[1]);
    const total = base + stiTarget + (ltiTarget ?? 0) + otherBonus;
    return {
        base_salary: base,
        sti_target: stiTarget,
        sti_max: Math.round(stiTarget * 1.5),
        lti_target: ltiTarget,
        lti_max: ltiTarget != null ? Math.round(ltiTarget * 1.5) : null,
        other_bonus: otherBonus,
        total_compensation: total,
    };
}

// ── ICPD content pools ──────────────────────────────────────────────────
// Every person gets fabricated-but-plausible content across every ICPD
// section, generated from their own role/function/grade/tenure rather than
// hand-written per person — see rngFor(name) above for why this is stable
// across reseeds instead of reshuffling on every `npm run wipe-and-reseed`.

const STRENGTHS = ["Business Strategy", "Customer Insight", "Brand Development", "Omnichannel Transformation", "Financial Acumen", "Talent Development", "Operational Excellence", "Digital Innovation", "Stakeholder Management", "Change Leadership"];
const DEV_AREAS = ["Operational leadership", "Cross-functional influence", "Public speaking", "Delegation", "Strategic prioritization", "International exposure", "Financial modelling", "Executive presence"];
const COMPETENCIES = ["Driving for Profitable Growth", "Striving to Meet Customer Satisfaction", "Building Organization Excellence", "Promoting Sustainable Collaborations & Partnerships", "Developing People", "Leading Innovation", "Strategic Thinking", "Commercial Acumen", "Resilience & Adaptability", "Collaborative Leadership"];
const RATINGS = ["Strong", "Developing", "Role Model"];
const DEGREES = [
    ["BA (Hons)", "Business Administration"], ["MSc", "Marketing"], ["MBA", "Management Studies"],
    ["BEng", "Industrial Engineering"], ["BA", "Economics"], ["MA", "International Business"],
    ["BSc", "Finance"], ["MA (Hons)", "History"],
];
const UNIVERSITIES = ["Cambridge", "Oxford", "London Business School", "INSEAD", "Bocconi", "HEC Paris", "Erasmus University", "Stockholm School of Economics", "Chulalongkorn University", "National University of Singapore"];

// Prior employers before joining Central Group — deliberately real-sounding
// but unrelated retail/consulting names, never one of our own 8 banners.
const EXTERNAL_COMPANIES = ["Harrods", "John Lewis Partnership", "Marks & Spencer", "Tesco", "Unilever", "L'Oréal", "Nestlé", "PwC", "Deloitte", "McKinsey & Company", "Accenture", "IKEA", "H&M", "Auchan", "Carrefour"];
const TITLE_LADDER = {
    Leadership: ["Regional Director", "VP Operations", "Head of Strategy"],
    Product: ["Product Manager", "Senior Product Manager", "Associate Director, Product"],
    "Human Resources": ["HR Manager", "HR Business Partner", "People & Culture Lead"],
    Finance: ["Finance Manager", "Senior Financial Analyst", "Finance Business Partner"],
    Marketing: ["Marketing Manager", "Brand Manager", "Senior Marketing Executive"],
    Operations: ["Operations Manager", "Supply Chain Manager", "Process Improvement Lead"],
};

// 1-3 prior roles (more for Execs, whose careers are longer) at outside
// companies, each ending right before the previous one starts, working
// backward from the person's actual Central Group hire date.
function generatePriorExperience(row) {
    const [name, , functionName, , grade, , hireDate] = row;
    const rng = rngFor(name + ":history");
    const ladder = TITLE_LADDER[functionName] || TITLE_LADDER.Operations;
    const numEntries = grade === "Exec" ? 3 : grade === "Manager" ? 2 : 1;
    const used = new Set();
    const entries = [];
    let cursorEnd = new Date(hireDate);
    cursorEnd.setDate(cursorEnd.getDate() - 1);
    for (let i = 0; i < numEntries; i++) {
        const durationYears = rngInt(rng, 2, 4);
        const start = new Date(cursorEnd);
        start.setFullYear(start.getFullYear() - durationYears);
        let company = pick(rng, EXTERNAL_COMPANIES);
        while (used.has(company) && used.size < EXTERNAL_COMPANIES.length) company = pick(rng, EXTERNAL_COMPANIES);
        used.add(company);
        entries.push({
            banner: company,
            position: ladder[Math.min(i, ladder.length - 1)],
            start_date: start.toISOString().slice(0, 10),
            end_date: cursorEnd.toISOString().slice(0, 10),
        });
        cursorEnd = new Date(start);
        cursorEnd.setDate(cursorEnd.getDate() - 1);
    }
    return entries;
}

const ACHIEVEMENTS_BY_FUNCTION = {
    Leadership: (rng) => [`Delivered ${rngInt(rng, 4, 12)}% growth in group EBIT`, `Led successful entry into ${rngInt(rng, 1, 3)} new markets`],
    Finance: (rng) => [`Delivered €${rngInt(rng, 150, 900)}k in annualized cost savings`, `Improved forecast accuracy to ${rngInt(rng, 88, 98)}%`],
    Marketing: (rng) => [`Grew loyalty membership by ${rngInt(rng, 50, 500)}k new members`, `Increased campaign ROI by ${rngInt(rng, 10, 40)}%`],
    Product: (rng) => [`Shipped ${rngInt(rng, 2, 6)} major product releases on schedule`, `Improved conversion rate by ${rngInt(rng, 5, 25)}%`],
    Operations: (rng) => [`Reduced operational costs by ${rngInt(rng, 5, 20)}%`, `Improved on-time delivery to ${rngInt(rng, 90, 99)}%`],
    "Human Resources": (rng) => [`Reduced voluntary attrition by ${rngInt(rng, 3, 15)}%`, `Delivered leadership program for ${rngInt(rng, 10, 60)}+ managers`],
};

const NEXT_STEP_BY_GRADE = {
    Exec: (fn) => `Expansion of remit to include additional ${fn} markets across the group`,
    Manager: (fn) => `Promotion to Head of ${fn}`,
    IC: (fn) => `Promotion to ${fn} Manager`,
};
const GRADE_UP = { IC: "Manager", Manager: "Exec", Exec: "Exec" };

const ASSESSMENT_LEVELS = ["Green", "Amber", "Red"];
const READINESS_LEVELS = ["Ready now", "Ready 1-3 yrs", "Not yet ready"];
const RISK_LEVELS = ["Low", "Medium", "High"];

// One bundle of every ICPD section's content for a single person, derived
// from their own row in EMPLOYEES (name/function/grade/banner/hire date) plus
// a name-seeded RNG so it reads as "this person's" data, not a copy-paste
// template, while staying identical across reseeds.
function generateIcpdContent(row) {
    const [name, bName, functionName, title, grade, , hireDate] = row;
    const rng = rngFor(name);
    const tenureYears = new Date().getFullYear() - new Date(hireDate).getFullYear();

    const strengths = pickN(rng, STRENGTHS, grade === "Exec" ? 3 : 2);
    const devAreas = pickN(rng, DEV_AREAS, 1);
    const [degree, major] = pick(rng, DEGREES);
    const university = pick(rng, UNIVERSITIES);

    const competencies = pickN(rng, COMPETENCIES, grade === "Exec" ? 5 : grade === "Manager" ? 4 : 3)
        .map((c) => ({ competency_name: c, rating: pick(rng, RATINGS) }));

    const achievements = (ACHIEVEMENTS_BY_FUNCTION[functionName] || ACHIEVEMENTS_BY_FUNCTION.Operations)(rng);

    const nextGrade = GRADE_UP[grade];
    const actionPlan = {
        plan: grade === "Exec" ? `Broaden scope across additional Central Group companies` : `Develop to ${nextGrade}-ready`,
        next_steps: NEXT_STEP_BY_GRADE[grade](functionName),
        by_when: `${["Jan", "Apr", "Jul", "Oct"][Math.floor(rng() * 4)]} ${new Date().getFullYear() + rngInt(rng, 1, 2)}`,
        status: pick(rng, ["In progress", "Not started", "On track"]),
    };
    const nextRolePrep = {
        by_when: String(new Date().getFullYear() + 1),
        next_steps: `${NEXT_STEP_BY_GRADE[grade](functionName)}. Mentoring and cross-functional exposure within ${bName}.`,
    };

    const careerStep = {
        destination_role: grade === "Exec" ? `Group ${functionName} leadership across Central Group` : NEXT_STEP_BY_GRADE[grade](functionName),
        level: nextGrade,
        by_year: new Date().getFullYear() + rngInt(rng, 1, 3),
        by_age: null,
        type: grade === "IC" ? "Promotion" : grade === "Manager" ? "Promotion" : "Expansion",
    };

    const assessments = [2024, 2025].map((fy) => ({
        fiscal_year: fy,
        performance: pick(rng, ASSESSMENT_LEVELS),
        commitment_engagement: pick(rng, ["High", "Medium", "Low"]),
        promotion_readiness: pick(rng, READINESS_LEVELS),
        risk_of_losing: pick(rng, RISK_LEVELS),
    }));

    const grades = [2023, 2024, 2025].map((fy) => ({
        fiscal_year: fy,
        grade: pick(rng, ["A", "B+", "B", "C"]),
        label: pick(rng, ["Exceeds Expectations", "Meets Expectations", "Strong Performer", "Solid Contributor"]),
    }));

    return { strengths, devAreas, degree, major, university, competencies, achievements, actionPlan, nextRolePrep, careerStep, assessments, grades, tenureYears };
}

// ── Insert ────────────────────────────────────────────────────────────────

// node:sqlite has no db.transaction() helper (unlike better-sqlite3), so
// BEGIN/COMMIT/ROLLBACK are driven by hand instead, via runInTransaction below.
const insertAll = () => {
    // Banners + their offices are already in the database (schema.sql inserts
    // the 8 real Central Group banners as built-in content) — look them up
    // rather than creating them.
    const bannerId = {};
    const officeId = {};
    const officeCountry = {};
    const officeCity = {};
    for (const row of db.prepare("SELECT banner_id, name FROM banners").all()) {
        bannerId[row.name] = row.banner_id;
    }
    for (const row of db.prepare("SELECT office_id, banner_id, country, city FROM banner_offices").all()) {
        const bannerName = Object.keys(bannerId).find((name) => bannerId[name] === row.banner_id);
        officeId[bannerName] = row.office_id;
        officeCountry[bannerName] = row.country;
        officeCity[bannerName] = row.city;
    }
    const missingBanners = [...new Set(EMPLOYEES.map((r) => r[1]))].filter((b) => !bannerId[b]);
    if (missingBanners.length > 0) {
        throw new Error(`Banner(s) not found in database: ${missingBanners.join(", ")} — run \`npm run setup\` on a fresh database first.`);
    }

    const functionId = {};
    const positionId = {};
    const employeeId = {};
    const employeePositionId = {};

    const insertFunction = db.prepare("INSERT INTO functions (name) VALUES (?)");
    for (const f of FUNCTIONS) {
        functionId[f] = insertFunction.run(f).lastInsertRowid;
    }

    const insertPosition = db.prepare(
        "INSERT INTO positions (title, banner_id, function_id) VALUES (?, ?, ?)"
    );
    const insertEmployee = db.prepare(`
        INSERT INTO employees (
            position_id, name, date_of_birth, nationality, country, city, status,
            banner_id, office_id, function_id, position_title, job_grade,
            hire_date, position_effective_date, readiness_potential, resign_date, resignation_reason, photo
        ) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);

    // Illustrated avatar per person — pre-generated once and committed under
    // assets/employee-photos/ (same pattern as assets/banner-logos/), copied
    // into place here rather than fetched from a stock-photo API at runtime:
    // an external URL would mean every profile-photo view calls out over the
    // internet, which breaks the "100% offline" guarantee this standalone
    // edition exists for.
    const photoDir = path.join(uploadsRoot, "profile-photos");
    mkdirSync(photoDir, { recursive: true });
    function photoUrlFor(name) {
        const file = `demo-${name.toLowerCase().replace(/[^a-z0-9]+/g, "-")}.png`;
        copyFileSync(path.join(photoSourceDir, file), path.join(photoDir, file));
        return `/api/files/profile-photos/${file}`;
    }

    for (const row of EMPLOYEES) {
        const [name, bName, functionName, title, grade, dob, hireDate, effDate, readiness, status] = row;
        const resignDate = row[11] ?? null;
        const resignReason = row[12] ?? null;
        const bId = bannerId[bName];
        const fId = functionId[functionName];
        const posKey = `${bId}:${title}:${fId}`;
        if (!positionId[posKey]) {
            positionId[posKey] = insertPosition.run(title, bId, fId).lastInsertRowid;
        }
        const posId = positionId[posKey];
        const empId = insertEmployee.run(
            posId, name, dob, officeCountry[bName], officeCountry[bName],
            officeCity[bName], status, bId, officeId[bName], fId, title, grade,
            hireDate, effDate, readiness, resignDate, resignReason, photoUrlFor(name)
        ).lastInsertRowid;
        employeeId[name] = empId;
    }

    const insertEmpPosition = db.prepare(`
        INSERT INTO employee_positions (
            employee_id, position_title, position_id, function_id, banner_id, office_id, is_primary, position_effective_date
        ) VALUES (?, ?, ?, ?, ?, ?, 1, ?)
    `);
    for (const row of EMPLOYEES) {
        const [name, bName, functionName, title, , , , effDate] = row;
        const bId = bannerId[bName];
        const fId = functionId[functionName];
        const posKey = `${bId}:${title}:${fId}`;
        employeePositionId[name] = insertEmpPosition.run(
            employeeId[name], title, positionId[posKey], fId, bId, officeId[bName], effDate
        ).lastInsertRowid;
    }

    // Office heads (informational only — banner_offices.country_head_id is not FK-enforced).
    // Only the 2 banners with people in this roster get one; the other 6
    // banners still exist (built-in, with their real logos) but have no
    // staff yet, same as any company before its first hire is entered.
    const headByBanner = {
        Selfridges: "Robert King", Arnotts: "Sofia Martinez",
    };
    const updateOfficeHead = db.prepare("UPDATE banner_offices SET country_head_id = ? WHERE office_id = ?");
    for (const [bName, headName] of Object.entries(headByBanner)) {
        updateOfficeHead.run(employeeId[headName], officeId[bName]);
    }

    // Reporting hierarchy — same edges reused across all 3 dimensions.
    const insertOrgEdge = db.prepare(
        "INSERT INTO org_edges (employee_position_id, parent_employee_position_id, dimension) VALUES (?, ?, ?)"
    );
    for (const dimension of ["banner", "function", "headcount"]) {
        for (const row of EMPLOYEES) {
            const [name, , , , , , , , , , reportsTo] = row;
            const parentPosId = reportsTo ? employeePositionId[reportsTo] : null;
            insertOrgEdge.run(employeePositionId[name], parentPosId, dimension);
        }
    }

    // Compensation.
    const insertComp = db.prepare(`
        INSERT INTO employee_compensation (
            employee_id, currency, base_salary, sti_target, sti_max, lti_target, lti_max, other_bonus, total_compensation
        ) VALUES (?, 'EUR', ?, ?, ?, ?, ?, ?, ?)
    `);
    const insertCompHistory = db.prepare(`
        INSERT INTO compensation_history (
            employee_id, fiscal_year, effective_date, base_salary, total_comp,
            sti_eligible_pct, sti_actual_pct, sti_amount, lti_eligible_pct, lti_actual_pct, lti_amount
        ) VALUES (?, 2025, '2025-01-01', ?, ?, ?, ?, ?, ?, ?, ?)
    `);
    for (const row of EMPLOYEES) {
        const [name, , , , grade] = row;
        const comp = mockCompensation(grade);
        insertComp.run(
            employeeId[name],
            encryptAmount(comp.base_salary), encryptAmount(comp.sti_target), encryptAmount(comp.sti_max),
            encryptAmount(comp.lti_target), encryptAmount(comp.lti_max), encryptAmount(comp.other_bonus),
            encryptAmount(comp.total_compensation)
        );
        const stiPct = GRADE_COMP[grade].sti * 100;
        const ltiPct = GRADE_COMP[grade].lti * 100;
        insertCompHistory.run(
            employeeId[name],
            encryptAmount(comp.base_salary), encryptAmount(comp.total_compensation),
            encryptAmount(stiPct), encryptAmount(stiPct), encryptAmount(comp.sti_target),
            encryptAmount(ltiPct || null), encryptAmount(ltiPct || null), encryptAmount(comp.lti_target)
        );
    }

    // ── ICPD content per person (background, competencies, action plans,
    //    achievements, periodic assessments, performance grades, one career
    //    step each, plus mentor + cross-group mobility on the employee row) ──
    const insertBackground = db.prepare(
        "INSERT INTO employee_background (employee_id, type, title, organization, detail, sort_order) VALUES (?, ?, ?, ?, ?, ?)"
    );
    const insertCompetency = db.prepare(
        "INSERT INTO employee_competencies (employee_id, competency_name, rating, sort_order) VALUES (?, ?, ?, ?)"
    );
    const insertDevPlan = db.prepare(
        "INSERT INTO employee_development_plans (employee_id, category, plan, next_steps, by_when, status) VALUES (?, ?, ?, ?, ?, ?)"
    );
    const insertAchievement = db.prepare(
        "INSERT INTO employee_achievements (employee_id, description, sort_order) VALUES (?, ?, ?)"
    );
    const insertAssessment = db.prepare(
        "INSERT INTO employee_periodic_assessments (employee_id, fiscal_year, performance, commitment_engagement, promotion_readiness, risk_of_losing) VALUES (?, ?, ?, ?, ?, ?)"
    );
    const insertGrade = db.prepare(
        "INSERT INTO performance_grades (employee_id, fiscal_year, grade, label) VALUES (?, ?, ?, ?)"
    );
    const insertCareerStep = db.prepare(
        "INSERT INTO employee_career_steps (employee_id, step_order, destination_role, level, function_id, by_year, by_age, type, banner_id) VALUES (?, 1, ?, ?, ?, ?, ?, ?, ?)"
    );
    const updateMentorMobility = db.prepare(
        "UPDATE employees SET mentor_employee_id = ?, cross_group_mobility = ? WHERE employee_id = ?"
    );
    const insertHistory = db.prepare(
        "INSERT INTO employment_history (employee_id, banner, position, location, start_date, end_date, is_current) VALUES (?, ?, ?, NULL, ?, ?, 0)"
    );

    for (const row of EMPLOYEES) {
        const [name, bName, functionName, , grade, , , , readiness, , reportsTo] = row;
        const empId = employeeId[name];
        const c = generateIcpdContent(row);

        generatePriorExperience(row).forEach((h) => insertHistory.run(empId, h.banner, h.position, h.start_date, h.end_date));

        insertBackground.run(empId, "education", c.degree, c.university, c.major, 1);
        c.strengths.forEach((s, i) => insertBackground.run(empId, "strength", s, null, null, i + 1));
        c.devAreas.forEach((s, i) => insertBackground.run(empId, "development_area", s, null, null, i + 1));

        c.competencies.forEach((comp, i) => insertCompetency.run(empId, comp.competency_name, comp.rating, i + 1));

        insertDevPlan.run(empId, "action_plan", c.actionPlan.plan, c.actionPlan.next_steps, c.actionPlan.by_when, c.actionPlan.status);
        insertDevPlan.run(empId, "next_role_prep", "Preparation", c.nextRolePrep.next_steps, c.nextRolePrep.by_when, null);

        c.achievements.forEach((a, i) => insertAchievement.run(empId, a, i + 1));

        c.assessments.forEach((a) => insertAssessment.run(empId, a.fiscal_year, a.performance, a.commitment_engagement, a.promotion_readiness, a.risk_of_losing));
        c.grades.forEach((g) => insertGrade.run(empId, g.fiscal_year, g.grade, g.label));

        insertCareerStep.run(empId, c.careerStep.destination_role, c.careerStep.level, functionId[functionName], c.careerStep.by_year, c.careerStep.by_age, c.careerStep.type, bannerId[bName]);

        const mentorId = reportsTo ? employeeId[reportsTo] : null;
        const mobility = readiness === "High" ? 1 : readiness === "Low" ? 0 : null;
        updateMentorMobility.run(mentorId, mobility, empId);
    }

    // Departments (light coverage).
    const insertDept = db.prepare(
        "INSERT INTO departments (name, owner_employee_id, office_id, function_id, headcount) VALUES (?, ?, ?, ?, ?)"
    );
    insertDept.run("HQ People Operations", employeeId["Sofia Martinez"], officeId["Selfridges"], functionId["Human Resources"], 3);

    // Performance (light coverage).
    const cycleId = db.prepare(
        "INSERT INTO performance_cycles (name, fiscal_year, start_date, end_date, status) VALUES ('FY2025 Review', 2025, '2025-01-01', '2025-12-31', 'active')"
    ).run().lastInsertRowid;
    const insertGoal = db.prepare(`
        INSERT INTO banner_goals (cycle_id, banner_id, title, description, category, metric_unit, target_value, actual_value, progress_pct, weight, sort_order)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
    `);
    const goalId = insertGoal.run(
        cycleId, bannerId["Selfridges"], "Grow flagship revenue", "Increase Selfridges revenue year over year",
        "Financial", "%", 10, 7.5, 75, 40, 1
    ).lastInsertRowid;
    const insertTarget = db.prepare(`
        INSERT INTO employee_targets (cycle_id, employee_position_id, employee_id, banner_id, banner_goal_id, title, description, category, metric_unit, target_value, actual_value, progress_pct, weight, status, sort_order)
        VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'active', ?)
    `);
    insertTarget.run(
        cycleId, employeePositionId["Alex Morgan"], employeeId["Alex Morgan"], bannerId["Arnotts"], goalId,
        "Ship v2 roadmap", "Deliver the next major product roadmap milestone", "Delivery", "%", 100, 60, 60, 30, 1
    );

    // A salary proposal + comparison (light coverage).
    const proposalId = db.prepare(`
        INSERT INTO salary_proposals (employee_id, status, justification, target_fiscal_year, effective_date)
        VALUES (?, 'draft', 'Strong FY2025 performance and expanded scope warrant a market adjustment.', 2026, '2026-01-01')
    `).run(employeeId["Alex Morgan"]).lastInsertRowid;
    const proposedComp = mockCompensation("Manager");
    db.prepare(`
        INSERT INTO salary_proposal_compensation (proposal_id, base_salary, cash_allowance, sti_eligible_pct, sti_amount, lti_eligible_pct, lti_amount)
        VALUES (?, ?, ?, ?, ?, ?, ?)
    `).run(
        proposalId, encryptAmount(Math.round(proposedComp.base_salary * 1.1)), encryptAmount(2000),
        encryptAmount(18), encryptAmount(proposedComp.sti_target), encryptAmount(10), encryptAmount(proposedComp.lti_target)
    );

    // Succession — CEO seat (candidate: Victor Pak) and CHRO seat (candidate:
    // Sofia Martinez), each with a couple of "Key Attributes Required" rows
    // (the succession_candidate_attributes table from the ICPD schema).
    const insertSeat = db.prepare(
        "INSERT INTO succession_seats (banner_id, position_id, employee_id, label, sort_order) VALUES (?, ?, ?, ?, ?)"
    );
    const insertCandidate = db.prepare(
        "INSERT INTO succession_candidates (seat_id, candidate_name, candidate_employee_id, readiness, rank) VALUES (?, ?, ?, ?, ?)"
    );
    const ATTRIBUTE_POOL = ["Operational leadership", "Strategic Thinking", "Financial Acumen", "Stakeholder Management", "Change Leadership"];
    const POTENTIAL_LEVELS = ["Ready", "Developing", "Emerging"];
    const insertAttribute = db.prepare(
        "INSERT INTO succession_candidate_attributes (candidate_id, attribute_name, potential, sort_order) VALUES (?, ?, ?, ?)"
    );
    function addAttributesFor(candidateId, seedName) {
        const rng = rngFor(seedName + ":attrs");
        pickN(rng, ATTRIBUTE_POOL, 2).forEach((attr, i) => insertAttribute.run(candidateId, attr, pick(rng, POTENTIAL_LEVELS), i + 1));
    }

    const SEATS = [
        { title: "Chief Executive Officer", incumbent: "Robert King", function: "Leadership", candidates: [["Victor Pak", "ready_now"]] },
        { title: "CHRO", incumbent: "Helena Voss", function: "Human Resources", candidates: [["Sofia Martinez", "ready_now"]] },
    ];
    SEATS.forEach((seat, i) => {
        const fId = functionId[seat.function];
        const seatPosId = positionId[`${bannerId["Selfridges"]}:${seat.title}:${fId}`];
        const seatId = insertSeat.run(bannerId["Selfridges"], seatPosId ?? null, employeeId[seat.incumbent], seat.title, i + 1).lastInsertRowid;
        seat.candidates.forEach(([candName, readiness], rank) => {
            const candidateId = insertCandidate.run(seatId, candName, employeeId[candName], readiness, rank + 1).lastInsertRowid;
            addAttributesFor(candidateId, candName);
        });
    });

    return { employeeCount: EMPLOYEES.length, bannerCount: Object.keys(bannerId).length };
};

function runInTransaction(fn) {
    db.exec("BEGIN");
    try {
        const result = fn();
        db.exec("COMMIT");
        return result;
    } catch (err) {
        db.exec("ROLLBACK");
        throw err;
    }
}

const result = runInTransaction(insertAll);

db.close();

console.log("=== Sample data seeded ===");
